// Tool schema (ToolInfo) in the Planner's tool catalog:
{
  name: "expand_prompt_section",
  description: "Returns deeper reference guidance for the Planner on a specific topic. Use this only when you actually need it — most turns don't. [+ a per-section WHEN TO USE / WHEN NOT TO USE block — see drift_note; live at expand_prompt_section.go:38-51]",
  parameters: { section: { type: 'string', description: 'Name of the section to expand. One of: <names>', enum: prompt.SectionNames() } },
  required: ['section']
}
// enum = prompt.SectionNames() = sorted ["evidence_routing", "examples", "success_criteria", "validation"]  (nomik REMOVED)
// Tool response: prompt.GetSection(params.section) — verbatim content of the named section (section_* entries)

// root.go:689 routes first arg 'prompt-section' → runPromptSection(os.Args[2:]) (root.go:468):
func runPromptSection(args []string) error {
    if len(args) < 1 { return fmt.Errorf("usage: act-agent prompt-section <name> — known names: %v", promptpkg.SectionNames()) }
    name := args[0]
    content, ok := promptpkg.GetSection(name)   // same sectionRegistry as the native tool
    if !ok { return fmt.Errorf("unknown section %q — known names: %v", name, promptpkg.SectionNames()) }
    if content == "" { return fmt.Errorf("section %q is currently empty", name) }
    fmt.Print(content)
    if !strings.HasSuffix(content, "\n") { fmt.Println() }
    return nil
}
// Gated: the shim binary calls tools.IsAllowed('planner', 'prompt-section') before exec.

// Tool JSON schema visible to the LLM via ToolInfo:
{
  name: "act_cli",
  parameters: {
    subcommand: {
      type: 'string',
      enum: AllowedSubcommandHeads('planner')
           // RoleSubcommands['planner'] = ['status','context','log','graph','pvm','message','task retry','task abandon','prompt-section']  (codebase REMOVED)
           // AllowedSubcommandHeads dedups compound heads: 'task retry'+'task abandon' → one 'task'
           // Result (order-of-first-appearance): ['status','context','log','graph','pvm','message','task','prompt-section']
    },
    args: { type: 'array', items: { type: 'string' } }
  },
  required: ['subcommand']
}

// IsAllowed enforcement at execution (act_cli_whitelist.go:99):
//   bare 'status' → subcommand=='status', any args
//   compound 'task retry' → subcommand=='task' AND args[0]=='retry'
//   compound 'task abandon' → subcommand=='task' AND args[0]=='abandon'
